mapper.insert:
INSERT INTO shop (user_id, shop_group_id, name)
SELECT e.user_id, e.shop_group_id, #{defaultName}
FROM shop_group e
JOIN template_shop_group g ON g.name = e.name AND g.template_id = #{templateId}
WHERE e.user_id = #{userId}
  AND NOT EXISTS (
      SELECT 1 FROM shop c
      WHERE c.user_id = e.user_id AND c.shop_group_id = e.shop_group_id AND c.name = #{defaultName}
  )
